#region Purpose
// Contract for opening one feedback item by id.
#endregion

#region Design
// The route id is generated by [ApiRoute]. The server returns the item only to its owner.
// Another principal and a missing id are the same 404. No UserId on the query.
// Attachments are the files linked at submit, oldest first. DownloadPath is app-rooted.
// The mock sample is text, not an image: the item page renders it as a link, because an
// img src would go to the real server, which MockWebApiService does not intercept.
// Task 314: Status and Activity are the filer's view of triage. The server leaves out internal
// notes and admin identities; the SPA renders what it is given.
#endregion

namespace TimeWarp.Architecture.Features.Feedback;

[ApiEndpoint]
[EndpointAuthorize
(
  Policy = PermissionIds.FeedbackFileSelf,
  AuthenticationSchemes = AuthenticationSchemeNames.IdentitySession + "," + AuthenticationSchemeNames.MockIdentitySession
)]
public static partial class GetFeedback
{
  [ApiRoute("api/Feedback/{FeedbackItemId:guid}", HttpVerb.Get)]
  public sealed partial class Query : IApiRequest, IQuery<OneOf<Response, SharedProblemDetails>>;

  public sealed class Validator : AbstractValidator<Query>
  {
    public Validator()
    {
      RuleFor(query => query.FeedbackItemId).NotEmpty();
    }
  }

  public sealed class Response : BaseResponse, ICloneable
  {
    /// <summary>Immutable (get-only members), so a State clone can share the instance.</summary>
    public object Clone() => this;

    public Guid FeedbackItemId { get; }
    public string Permalink { get; }
    public FeedbackKind Kind { get; }
    public string Title { get; }
    public string Body { get; }
    public DateTimeOffset FiledAt { get; }
    public IReadOnlyList<Attachment> Attachments { get; }
    public FeedbackStatus Status { get; }
    public IReadOnlyList<FeedbackActivityEntry> Activity { get; }

    public Response(
      Guid feedbackItemId,
      string permalink,
      FeedbackKind kind,
      string title,
      string body,
      DateTimeOffset filedAt,
      IReadOnlyList<Attachment>? attachments = null,
      FeedbackStatus status = FeedbackStatus.New,
      IReadOnlyList<FeedbackActivityEntry>? activity = null)
    {
      FeedbackItemId = Guard.Against.NullOrEmpty(feedbackItemId);
      Permalink = Guard.Against.NullOrWhiteSpace(permalink);
      if (!Enum.IsDefined(kind))
      {
        throw new ArgumentException("Kind must be a defined feedback kind.", nameof(kind));
      }

      Kind = kind;
      Title = Guard.Against.NullOrWhiteSpace(title);
      Body = Guard.Against.NullOrWhiteSpace(body);
      FiledAt = filedAt;
      Attachments = attachments ?? [];
      if (!Enum.IsDefined(status))
      {
        throw new ArgumentException("Status must be a defined feedback status.", nameof(status));
      }

      Status = status;
      Activity = activity ?? [];
    }
  }

  public sealed class Attachment : ICloneable
  {
    /// <summary>Immutable (get-only members), so a State clone can share the instance.</summary>
    public object Clone() => this;

    public Guid AttachmentId { get; }
    public string FileName { get; }
    public string ContentType { get; }
    public long Size { get; }
    public string DownloadPath { get; }
    public bool IsImage { get; }

    public Attachment(
      Guid attachmentId,
      string fileName,
      string contentType,
      long size,
      string downloadPath)
    {
      AttachmentId = Guard.Against.NullOrEmpty(attachmentId);
      FileName = Guard.Against.NullOrWhiteSpace(fileName);
      ContentType = Guard.Against.NullOrWhiteSpace(contentType);
      ArgumentOutOfRangeException.ThrowIfNegativeOrZero(size);

      Size = size;
      DownloadPath = Guard.Against.NullOrWhiteSpace(downloadPath);
      IsImage = contentType.StartsWith("image/", StringComparison.Ordinal);
    }
  }

  public static MockResponseFactory<Response> GetMockResponseFactory()
  {
    var feedbackItemId = Guid.Parse("11111111-1111-1111-1111-111111111111");
    return request =>
    {
      Guid id = request is Query { FeedbackItemId: var routeId } && routeId != Guid.Empty
        ? routeId
        : feedbackItemId;
      var sampleId = Guid.Parse("22222222-2222-2222-2222-222222222222");
      Attachment sample = new(
        sampleId,
        "mock.txt",
        FeedbackAttachmentRules.Text,
        size: 1,
        DownloadFeedbackAttachment.DownloadPath(sampleId));
      return new Response(
        id,
        $"/Feedback/{id:D}",
        FeedbackKind.Complaint,
        "Mock complaint",
        "Mock body",
        DateTimeOffset.Parse("2026-10-09T00:00:00Z"),
        [sample],
        FeedbackStatus.UnderReview,
        [
          new FeedbackActivityEntry(
            1,
            FeedbackActivityKind.StatusChange,
            null,
            null,
            FeedbackStatus.New,
            FeedbackStatus.UnderReview,
            DateTimeOffset.Parse("2026-10-09T01:00:00Z")),
          new FeedbackActivityEntry(
            2,
            FeedbackActivityKind.AdminReply,
            null,
            "Thanks, we are looking.",
            null,
            null,
            DateTimeOffset.Parse("2026-10-09T02:00:00Z")),
        ]);
    };
  }
}
